import {expect,it} from 'vitest';
import {cockpitProfileSnapshot,cockpitCompleteValue} from './cockpitReport';
import type {CockpitSnapshot} from './cockpitTypes';
import generatedResponse from '../tests/fixtures/cockpit-response.json';
it('accepts the actual Fantom serializer fixture and agrees with the independent 40 kWh expectation',()=>{
 // Generated by EnerCubixCockpitTest in backend commit bc3496b8, not a hand-built transport response.
 const snapshot=generatedResponse as unknown as CockpitSnapshot;
 const before=structuredClone(snapshot),display=cockpitProfileSnapshot(snapshot)!;
 expect(snapshot.modules.kpis?.data?.values[0]).toMatchObject({value:40,completeValue:40,unit:'kWh',sourceIds:['pa','pb']});
 expect(display.result.series[0].points.map(point=>point.value)).toEqual([14,26]);
 expect(display.result.series[0].points.map(cockpitCompleteValue)).toEqual([14,26]);
 expect(snapshot).toEqual(before);
});
it('projects available usage for the chart without overwriting strict values or the frozen backend result',()=>{
 const point=Object.freeze({ts:'2026-10-01T00:00:00+08:00',value:null,valueType:'null',quality:'missing',knownValue:40,knownValueType:'number',knownQuality:'filtered',sourceIds:['primary']});
 const series=Object.freeze({id:'s',name:'Meter',unit:'kWh',points:[point]});
 const source={context:{project:'test',reportScope:{dimension:'space',nodeIds:['site']},focusCategoryId:'energy',time:{from:'2026-10-01T00:00:00+08:00',to:'2026-10-31T14:37:00+08:00',period:'day'},asOf:'2026-10-31T14:37:00+08:00'},generatedAt:'2026-10-31T14:37:03+08:00',modules:{trend:{data:{reportRef:'profile'}}},reports:{profile:{kind:'profile',from:'2026-10-01T00:00:00+08:00',to:'2026-10-31T14:37:00+08:00',period:'day',series:[series],rows:[],summary:{},warnings:[]}}} as unknown as CockpitSnapshot;
 const display=cockpitProfileSnapshot(source);
 expect(display).toBeDefined();expect(display?.result.series[0].points[0]).toMatchObject({value:40,completeValue:null,quality:'filtered'});
 expect(source.reports.profile.series[0].points[0].value).toBeNull();
 expect(cockpitCompleteValue(display!.result.series[0].points[0])).toBeNull();
 expect(cockpitCompleteValue({...display!.result.series[0].points[0],value:40,completeValue:0,completeQuality:'ok',completeValueType:'number'})).toBe(0);
 expect(cockpitCompleteValue({...display!.result.series[0].points[0],completeValue:40,completeQuality:'substituted',completeValueType:'number'})).toBeNull();
});
